const allLeads = $input.all().map(i => i.json);
const chat_id = $('Нормализовать chat_id (превью)').first().json.chat_id;
const leadsWithUsername = allLeads.filter(l => l.username && l.username.trim() !== '');
const totalCount = leadsWithUsername.length;
const previewLeads = leadsWithUsername.slice(0, 3);
if (totalCount === 0) return [{ json: { chat_id, totalCount: 0, previewText: 'Нет горячих лидов (A) с username для отправки.', noLeads: true } }];
let previewText = `👥 *Найдено ${totalCount} горячих лидов (A) с username*\n\n📋 *Примеры лидов:*\n\n`;
previewLeads.forEach((lead, idx) => {
  const username = lead.username ? '@' + lead.username : 'нет';
  const preview = (lead.text || '').substring(0, 150) + ((lead.text || '').length > 150 ? '...' : '');
  previewText += `${idx + 1}. ${username}\n   📢 ${lead.channel || ''}\n   💬 ${preview}\n   🎯 ${lead.ai_reason || ''}\n\n`;
});
previewText += `\n✉️ Буду отправлять персонализированные сообщения каждому.`;
return [{ json: { chat_id, totalCount, previewText, noLeads: false } }];

const allLeads = $input.all().map(i => i.json);
const chat_id = $('Нормализовать chat_id (execute)').first().json.chat_id;
const leadsWithUsername = allLeads.filter(l => l.username && l.username.trim() !== '');
if (leadsWithUsername.length === 0) return [{ json: { chat_id, noLeads: true, totalCount: 0 } }];
return leadsWithUsername.map(lead => ({ json: { ...lead, chat_id } }));

