const aiResult = $input.first().json;
// FIX: use .item.json to get current lead, not always the first one
const leadData = $('Фильтровать лидов с username').item.json;
let messageText = '';
try {
  messageText = aiResult.choices[0].message.content.trim();
} catch(e) {
  messageText = 'Здравствуйте! Увидел ваш пост и хотел бы обсудить возможное сотрудничество. Напишите, если интересно!';
}
return [{ json: { ...leadData, generated_message: messageText } }];

const sendResult = $input.first().json;
// FIX: use .item.json to get current lead, not always the first one
const leadData = $('Извлечь сгенерированное сообщение').item.json;
const success = sendResult.success === true || sendResult.status === 'ok' || sendResult.status === 'sent';
const error = sendResult.error || sendResult.message || '';
return [{ json: { ...leadData, send_success: success, send_error: error, contacted_at: new Date().toISOString() } }];

const allUpdated = $input.all().map(i => i.json);
const chat_id = allUpdated.length > 0 ? (allUpdated[0].chat_id || '7984101063') : '7984101063';
const total = allUpdated.length;
const successful = allUpdated.filter(l => l.send_success === true).length;
const errors = total - successful;
return [{ json: { chat_id, total, successful, errors } }];

const channels = $input.all()
  .map(i => i.json.channel_url || i.json.username || '')
  .map(c => c.replace('https://t.me/', '').replace('@','').trim())
  .filter(c => c);

const chatId = $('Нормализовать chat_id (превью)').first().json.chat_id;

// Get niche keywords from sources if available, else use generic lead signals
const sources = $input.all().map(i => i.json);
const nicheKeywords = sources
  .map(s => s.niche || '')
  .filter(k => k)
  .slice(0, 10);

return [{ json: {
  channels: channels,
  keywords: nicheKeywords.length > 0 ? nicheKeywords : ['ищу', 'нужен', 'куплю', 'ищем', 'требуется'],
  days_back: 7,
  messages_limit: 100,
  chat_id: chatId
}}];

const data = $input.first().json;
const leads = data.results || data.leads || data.raw_data || [];
if (!leads || leads.length === 0) return [];
return leads.map(l => ({ json: l }));

